def src(id,title,url,status,note):return dict(id=id,title=title,citation=title,url=url,verification=dict(status=status,checked_on=DAY,note=note))
sources=[
 src(REDDY,'William M. Reddy, The Navigation of Feeling: A Framework for the History of Emotions (Cambridge University Press, 2001), publisher frontmatter and preface.','https://assets.cambridge.org/97805218/03038/frontmatter/9780521803038_frontmatter.pdf','supporting_page_checked','Publisher frontmatter read: copyright/title pages, contents and preface ix–xiii. The copyright page explicitly says first published 2001. Reddy rejects a simple cultural/biological alternative, treats emotion and expression as interacting, and outlines the French 1700–1850 case. The body chapters and conclusion were not read. The definitions and later qualifications of emotives/regimes are read in his own 2010 interview answers, recorded separately. No claim that the proposed field originated in 2001.'),
 src(ROS,'Barbara H. Rosenwein, “Worrying about Emotions in History,” American Historical Review 107, no. 3 (June 2002), 821–845.','https://academic.oup.com/ahr/article-abstract/107/3/821/18881','supporting_page_checked','Published article selected pages 821–822, 826–828 and 842–845 read from the public University of Trieste institutional teaching copy: https://moodle2.units.it/pluginfile.php/366241/mod_resource/content/1/Worrying%20about%20Emotions%20in%20History.pdf . Scanned body pages were OCR-read; printed-page numbers are the locators. Pages 821–822 identify Febvre’s 1941 programme; 826–827 reconstruct and criticize the Elias-associated progressive-restraint narrative; 842–845 propose overlapping emotional communities and distinguish representation from transparent access to actual feelings. The remainder is unread. Publisher issue metadata and the copy’s title page establish June 2002; the Naples repository discovery record misleadingly displays 2001 and was not used for dating. This is Rosenwein’s argument and criticism, not a settled verdict on Elias.'),
 src(INTERVIEW,'Jan Plamper, “The History of Emotions: An Interview with William Reddy, Barbara Rosenwein, and Peter Stearns,” History and Theory 49, no. 2 (May 2010), 237–265.','https://doi.org/10.1111/j.1468-2303.2010.00541.x','supporting_page_checked','Publisher metadata/abstract checked: May 2010, 237–265; interviewer/credited author Jan Plamper, with the three named interviewees. Selected primary answers read in the author-uploaded text at https://www.researchgate.net/publication/261926040_THE_HISTORY_OF_EMOTIONS_AN_INTERVIEW_WITH_WILLIAM_REDDY_BARBARA_ROSENWEIN_AND_PETER_STEARNS (upload credited to Barbara Rosenwein): Reddy 237–238 (labour/contracts and emotion), 240–243 (emotives and plural regimes); Rosenwein 255–256 (criticism of the regime/refuge binary); Reddy’s plural-regime answer at 243 is retained alongside her objection. Other sections not systematically read; Stearns’s section unread. No whole-book reading is claimed. Search-page January dating was rejected in favor of the publisher’s May issue metadata.'),
 src(IDENTITY,'Barbara H. Rosenwein, Loyola University Chicago: emerita faculty profile and selected bibliography.','https://www.luc.edu/history/people/facultyandstaffdirectory/emeritusfaculty/profiles/rosenweinbarbarah.shtml','bibliographic_metadata_checked','Institutional profile identifies the named medieval/emotions historian and lists Emotional Communities in the Early Middle Ages (Cornell, 2006; paperback 2007). Identity also agrees with her primary 2002 article’s byline/author note and its Loyola affiliation. Reuses no other Rosenwein identity. No birth date, external authority ID or biography interval assigned. The book body is unread; this page supports the work/edition dates and identity, while methodological claims use her own 2002 article and 2010 answers. The profile gives conflicting 2015/2016 dates for Generations of Feeling; that later work is outside this bounded packet and is not dated here.')]
roster=[
 dict(person_id='william_m_reddy',role='historian',context='Emotives connect expression with the attempt to shape or explore feeling; regimes concern enforced norms. His 2010 answers allow plural regimes rather than requiring one nation-wide style.',works='The Navigation of Feeling (2001), preface; answers in Plamper’s interview (2010), 237–243',source_ids=[REDDY,INTERVIEW],basis='source_review'),
 dict(person_id='barbara_h_rosenwein',role='historian',context='Proposes overlapping emotional communities and challenges a single trajectory toward emotional restraint. Her objection to the regime/refuge model remains distinct from Reddy’s plural-regime qualification.',works='“Worrying about Emotions in History” (2002); Emotional Communities in the Early Middle Ages (2006; paperback 2007); answers in Plamper’s interview (2010)',source_ids=[ROS,IDENTITY,INTERVIEW],basis='source_review'),
 dict(person_id='lucien_febvre',role='precursor',context='The 1941 programme is an earlier call for historical inquiry into collective feelings. Rosenwein revisits its assumptions as well as its importance; this is not a claim that he founded all emotions history.',works='“La sensibilité et l’histoire” (1941); reprinted in Combats pour l’histoire (1953)',source_ids=[FEB,ROS],basis='source_review'),
 dict(person_id='elias',role='comparison',context='The Civilizing Process is a named interlocutor in Rosenwein’s criticism of progressive emotional restraint; inclusion records a disputed interpretation, not membership in a unified emotions school.',works='The Civilizing Process (1939), as discussed critically by Rosenwein (2002), 826–827',source_ids=[ROS],basis='source_review')]
def strand(id,title,focus,people,works,refs):return dict(id=id,title=title,focus=focus,person_ids=people,works=works,source_ids=refs,basis='editorial_distinction')
strands=[
 strand('dc166_earlier_programme','Earlier programmes and their assumptions','Febvre’s call makes feelings part of historical explanation. Rosenwein’s retrospective also questions his separation of emotional and intellectual life; an earlier resource need not supply the later method unchanged.',['lucien_febvre','barbara_h_rosenwein'],'Febvre (1941); Rosenwein (2002), 821–822',[FEB,ROS]),
 strand('dc166_emotives_regimes','Emotives and enforced emotional norms','Reddy treats speaking about feeling as an intervention that may alter experience or expose an unexpected response. Regimes concern sanctions and conformity as well as shared styles; his 2010 account permits several within a wider polity.',['william_m_reddy'],'The Navigation of Feeling (2001), preface ix–xiii; Reddy in Plamper (2010), 240–243',[REDDY,INTERVIEW]),
 strand('dc166_emotional_communities','Communities, movement and source interpretation','Rosenwein studies emotional valuations and expected expressions across overlapping social groups. Movement between settings matters. Her Gregory of Tours example examines an author’s emotional representation without assuming the narrated conversation actually occurred.',['barbara_h_rosenwein'],'“Worrying about Emotions in History” (2002), 842–845; Emotional Communities in the Early Middle Ages (2006), metadata only',[ROS,IDENTITY]),
 strand('dc166_periodization_critique','Against one progressive-restraint narrative','Rosenwein challenges an Elias-associated account that makes medieval emotion unrestrained and modernity controlled. Her alternative follows changing communities and relations between them; the critique does not make historical variation itself disappear.',['barbara_h_rosenwein','elias'],'Rosenwein (2002), 826–827, 842–845',[ROS]),
 strand('dc166_regimes_communities_dispute','Regimes and communities: a disagreement with qualifications','Rosenwein objects to a dominant regime/refuge binary; Reddy explicitly accepts plural regimes and emphasizes enforceable norms. These positions partly overlap but are not interchangeable, and neither is an editorially settled theory.',['william_m_reddy','barbara_h_rosenwein'],'Answers in Plamper’s interview (2010): Reddy 243; Rosenwein 255–256',[INTERVIEW])]
